import React from 'react'
import NavBar from './NavBar'
import BasicInput from '../Components/BasicInput'
import { LiaTableTennisSolid } from "react-icons/lia";
import CustomButton from '../Components/CustomButton';


const Home = () => {
  return (
    <div className=' flex flex-col justify-between p-5 relative h-screen rounded-xl my-2  bg-no-repeat w-full bg-cover z-0   bg-homebg'>

        <NavBar/>
        <div className=' flex gap-3'>
            <div className=' flex-1 text-white '>
<p className=' text-H'>BT's TT Academy</p>
<p>Freelance Table Tennis Coach | Table Tennis for everyone.</p>
      </div>

      <div className=' flex-1 rounded-2xl bg-black/35 backdrop-blur-md p-3'>
      {/* <LiaTableTennisSolid className=' text-3xl text-orange-500' />  */}
     <p className=' text-stone-200 text-sm bg-gradient-to-r from-orange-500 via-orange-500 to-orange-600 p-1 rounded-md shadow-md'>
  You can use this chat facility to clear any of your queries prior to Bookings ....
</p>
      
<BasicInput
labelName="Name"
fieldName="name"
placeholder="Enter your Name"s
/>
<BasicInput
        labelName="Phone Number"
        fieldName="phoneNumber"
        type="number"
        placeholder="Enter your phone number"
        // value={formData.phoneNumber}
        // onChange={handleChange}
        // error={!!errors.phoneNumber}
        // helperText={errors.phoneNumber}
      />

       <BasicInput
        labelName="Your Question"
        fieldName="question"
        type="multiline"
        placeholder="Try asking a detailed question"
        // value={formData.message}
        // onChange={handleChange}
      />
      <div>

      <CustomButton  size='small' text="Send Message"/>
      </div>
        
      
      </div>
        </div>
      
    </div>
  )
}

export default Home
